function tr(key){if(key==='imAdult')return 'Ich bin mindestens 16 Jahre alt.';if(key==='adultOnly')return 'Du musst mindestens 16 Jahre alt sein.';if(key==='under18')return 'Person möglicherweise unter 16';const extra={no:'Nein',reels:'Reels',privacy:'Datenschutz',help:'Wie können wir dir helfen?',legal:'Rechtliches'};return words.de[key]||extra[key]||key;}
const svg=(name)=>icon(name);
function badge(p){return p?.official?`<span class="verified" title="${esc(p?.official?tr('verified'):tr('moderator'))}">${svg('check')}</span>`:'';}
function avatar(p,size=''){const img=p?.photoId||p?.photos?.[0];return `<span class="avatar ${size}">${img?`<img src="/api/photos/${encodeURIComponent(img)}" alt="" loading="lazy">`:icon('user')}</span>`;}
function showFormError(msg){if($('#modal')?.open){let e=$('#modal .modal-error');if(!e){e=document.createElement('p');e.className='modal-error';$('#modalBody').prepend(e)}e.textContent=msg;e.scrollIntoView({block:'nearest'});}else toast(msg);}
function toast(msg){const e=$('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(toast.tm);toast.tm=setTimeout(()=>e.classList.remove('show'),4000);}
async function api(path,opts={}){const res=await fetch('/api'+path,{credentials:'same-origin',...opts});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Technischer Fehler. Bitte versuche es erneut.');return data;}
const post=(p,d)=>api(p,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(d)});
const patch=(p,d)=>api(p,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(d)});
const del=p=>api(p,{method:'DELETE'});
const profileImg=id=>id?`/api/photos/${encodeURIComponent(id)}`:null;
const socialImg=id=>id?`/api/social/media/${encodeURIComponent(id)}`:null;
function dateTime(v){if(!v)return '';const v2=/^\d{4}-\d{2}-\d{2} /.test(v)?v.replace(' ','T')+'Z':v;try{return new Intl.DateTimeFormat('de-DE',{dateStyle:'medium'}).format(new Date(v2));}catch{return '';}}
function dateTimeFull(v){
 if(!v)return 'Noch nicht erfasst';
 const iso=/^\d{4}-\d{2}-\d{2} /.test(v)?v.replace(' ','T')+'Z':v;
 const d=new Date(iso);if(Number.isNaN(d.getTime()))return 'Unbekannt';
 return new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Berlin'}).format(d)+' Uhr';
}
function formatCount(n){return Number(n||0).toLocaleString('de-DE');}
const ask=(title,desc,yes)=>new Promise(resolve=>{let done=false;const finish=value=>{if(done)return;done=true;$('#modal').removeEventListener('close',onClose);resolve(value)};const onClose=()=>finish(false);openModal(`<h2>${esc(title)}</h2><p>${esc(desc||'')}</p><div class="split-actions inline-buttons"><button class="button outlined" id="modalNo">Nein</button><button class="button primary" id="modalYes">${esc(yes||tr('submit'))}</button></div>`);$('#modal').addEventListener('close',onClose,{once:true});$('#modalNo').onclick=()=>{finish(false);closeModal()};$('#modalYes').onclick=()=>{finish(true);closeModal()};});
function openModal(html){$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){if(model.storyPreviewUrl){URL.revokeObjectURL(model.storyPreviewUrl);model.storyPreviewUrl=null;}if($('#modal').open)$('#modal').close();$('#modalBody').innerHTML='';}
$('#closeModal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
function setLang(l,sync=true){model.lang='de';document.documentElement.lang=model.lang;storage.setItem('kn.locale',model.lang);document.querySelectorAll('[data-t]').forEach(e=>{e.textContent=tr(e.dataset.t)});if(model.me){shell();navigate(model.route)}if(sync&&model.me)patch('/settings',{locale:model.lang,chatLocale:model.lang,theme:model.theme}).catch(()=>{});}
function setTheme(t,sync=true){model.theme=['system','dark','light'].includes(t)?t:'system';document.documentElement.dataset.theme=model.theme;storage.setItem('kn.theme',model.theme);if(sync&&model.me)patch('/settings',{locale:model.lang,chatLocale:model.lang,theme:model.theme}).catch(()=>{});}
function navLinks(){const arr=[['feed','home'],['explore','compass'],['create','plus'],['messages','mail'],['notifications','bell'],['profile','user']];if(model.me?.role)arr.push(['admin','shield']);return arr;}
