function openMenu(){
 const drawer=$('#menuDrawer');if(!drawer)return;
 drawer.innerHTML=`<div class="drawer-head"><div class="drawer-brand"><img src="/assets/kennely-icon.png" alt=""><div><strong>kennely<span>.</span></strong><small>Dein Menü</small></div></div><button type="button" class="icon-button" data-menu-close aria-label="Menü schließen">×</button></div><div class="drawer-account">${avatar(model.me)}<div><strong>${esc(model.me?.name||'')}</strong><small>@${esc(model.me?.username||'')}</small></div>${model.me?.role==='owner'?'<span class="tag ceo-tag">CEO</span>':''}</div>${menuItems().map(group=>`<section class="drawer-group"><h3>${esc(group.title)}</h3>${group.items.map(([route,ico,label])=>`<button type="button" class="drawer-link ${model.route===route?'active':''}" data-go="${route}">${icon(ico)}<span>${esc(label)}</span><span aria-hidden="true">›</span></button>`).join('')}</section>`).join('')}<div class="drawer-footer"><button class="drawer-link" data-logout>${icon('logout')}<span>Abmelden</span><span>›</span></button><div class="drawer-legal"><a href="/legal/impressum">Impressum</a><a href="/legal/datenschutz">Datenschutz</a><a href="/legal/regeln">Regeln</a><a href="/legal/beschwerden">Einspruch</a></div></div>`;
 model.menuOpen=true;drawer.hidden=false;$('#menuBackdrop').hidden=false;document.body.classList.add('drawer-visible');drawer.querySelector('[data-menu-close]')?.focus();
}
function closeMenu(){model.menuOpen=false;const d=$('#menuDrawer'),b=$('#menuBackdrop');if(d)d.hidden=true;if(b)b.hidden=true;document.body.classList.remove('drawer-visible');}
function shell(){const u=model.me||{};$('#nav').innerHTML=navLinks().map(([n,ico])=>`<button class="nav-item ${model.route===n?'active':''}" data-go="${n}">${icon(ico)}<span>${tr(n)}</span>${n==='notifications'?'<span class="number-badge" id="navBadge" hidden></span>':''}</button>`).join('');$('#mobileNav').innerHTML=['feed','explore','create','messages','profile'].map(n=>{const ico=navLinks().find(x=>x[0]===n)?.[1]||'home';return `<button class="nav-item ${model.route===n?'active':''} ${n==='create'?'mobile-create':''}" data-go="${n}" aria-label="${tr(n)}">${n==='create'?'<span class="center-plus" aria-hidden="true">+</span>':icon(ico)}${n==='create'?'':`<span>${tr(n)}</span>`}${n==='messages'?'<span id="mobileMessageUnread" class="number-badge" hidden></span>':''}</button>`}).join('');$('#identity').innerHTML=`${avatar(u,'small')}<div><strong>${esc(u.name||u.username||'')}</strong> ${badge(u)}<br><small>${u.username?'@'+esc(u.username):'Benutzername fehlt'} ${u.role==='owner'?'· CEO':''}</small></div>`;setBadgeNumber(model.unreadCount);setMessageBadge(model.messageUnread);const te=$('#mobileTeamEntry');if(te)te.hidden=!u.role;}
function mountUser(u){if(u?.suspended){mountSuspended(u);return;}document.body.classList.remove('kn-suspended');model.me=u;$('#guest').classList.add('hidden');$('#shell').classList.remove('hidden');shell();document.documentElement.classList.remove('kn-booting');if(!u.emailVerified&&!['localhost','127.0.0.1'].includes(location.hostname)){display(`<div class="panel"><h2>${tr('emailVerify')}</h2><button class="button primary" id="resend">${tr('resend')}</button></div>`);$('#resend').onclick=()=>post('/auth/resend-verification',{}).then(()=>toast(tr('success'))).catch(e=>toast(e.message));return;}const locationRoute=location.pathname;
 const routes={'/':'feed','/home':'feed','/entdecken':'explore','/nachrichten':'messages','/mitteilungen':'notifications','/gespeichert':'saved','/aktivitaeten':'activity','/einstellungen':'settings','/team':'admin','/support':'support'};
 if(locationRoute.startsWith('/profil/')){model.route='profile';renderProfile(locationRoute.slice('/profil/'.length)).catch(()=>navigate('feed'));}
 else if(locationRoute.startsWith('/nachrichten/')){const tid=decodeURIComponent(locationRoute.slice('/nachrichten/'.length));navigate('messages',{pop:true}).then(()=>openThread(tid,false)).catch(()=>navigate('messages'));}
 else navigate(routes[locationRoute]||'feed',{pop:true});
 document.documentElement.classList.remove('kn-booting');connectLive();updateBadge();updateMessageBadge();}
function mountGuest(){document.body.classList.remove('kn-suspended');document.documentElement.classList.remove('kn-booting');model.viewCache=Object.create(null);model.me=null;$('#shell').classList.add('hidden');$('#guest').classList.remove('hidden');disconnectLive();setLang(model.lang,false);}
function mountSuspended(u){
 model.me=u;model.route='suspended';model.viewCache=Object.create(null);model.activeThread=null;
 disconnectLive();closeMenu();$('#guest').classList.add('hidden');$('#shell').classList.remove('hidden');
 $('#nav').innerHTML='';$('#mobileNav').innerHTML='';$('#rightRail').innerHTML='';
 document.body.classList.add('kn-suspended');document.documentElement.classList.remove('kn-booting');
 renderSuspended();
}
async function renderSuspended(){
 if(!model.me?.suspended)return;
 const root=$('#content');
 root.innerHTML=`<div class="kn-ban-page"><header class="kn-ban-head"><a href="/legal/regeln" class="kn-ban-brand"><img src="/assets/kennely-icon.png" alt=""/> kennely<span>.</span></a><span>Konto-Status</span></header><main class="kn-ban-content"><div class="kn-ban-avatar">${avatar(model.me,'big')}</div><h1>Wir haben dein Konto deaktiviert</h1><p class="kn-ban-subtitle">Du kannst Kennely derzeit nicht wie gewohnt nutzen.</p><div class="kn-ban-loading">Deine Entscheidung wird geladen …</div></main></div>`;
 try{
  const r=await api('/account/suspension');if(!model.me?.suspended)return;
  const state=r.state||{},status=state.appealStatus||'none';
  const appeal=status==='open'?`<div class="kn-ban-message" role="status"><strong>Dein Einspruch wurde eingereicht.</strong><p>Unser Team überprüft die Entscheidung. Du kannst den Status hier sehen, ohne die Einstellungen zu öffnen.</p></div>`:
   status==='rejected'?`<div class="kn-ban-message"><strong>Dein Einspruch wurde abgelehnt.</strong><p>Du kannst weitere Informationen zu Beschwerdemöglichkeiten einsehen.</p></div>`:
   status==='accepted'?`<div class="kn-ban-message"><strong>Dein Einspruch wurde angenommen.</strong><p>Lade die Seite neu, um deinen Kontostatus zu aktualisieren.</p><button type="button" data-retry-page class="button outlined">Status aktualisieren</button></div>`:
   `<section class="kn-ban-appeal"><h2>Entscheidung überprüfen lassen</h2><p>Du kannst direkt hier Einspruch einlegen. Beschreibe, weshalb du mit der Entscheidung nicht einverstanden bist.</p><form id="suspendedAppealForm" class="column"><label class="field" for="suspensionAppealText">Deine Begründung<textarea id="suspensionAppealText" name="reason" minlength="15" maxlength="1800" required placeholder="Erkläre deine Sicht auf die Entscheidung …"></textarea><small>Mindestens 15 Zeichen</small></label><button type="submit" class="button primary">Einspruch einreichen</button></form></section>`;
  root.innerHTML=`<div class="kn-ban-page"><header class="kn-ban-head"><a class="kn-ban-brand" href="/legal/regeln"><img src="/assets/kennely-icon.png" alt=""/> kennely<span>.</span></a><span>Konto-Status</span></header><main class="kn-ban-content"><div class="kn-ban-avatar">${avatar(model.me,'big')}</div><h1>Wir haben dein Konto deaktiviert</h1><p class="kn-ban-subtitle">Du kannst derzeit nicht auf dein Profil zugreifen.</p><p class="kn-ban-date">Konto deaktiviert am ${dateTime(state.suspendedAt)||'–'}</p><section class="kn-ban-section"><h2>Warum das passiert ist</h2><p>${esc(state.reason||'Dein Konto wurde nach einer Moderationsentscheidung eingeschränkt.')}</p><p class="kn-ban-muted">Betroffene Regel: ${esc(state.ruleId||'Community-Regeln')}</p><a href="/legal/regeln">Mehr zu unseren Regeln ›</a></section><section class="kn-ban-section"><h2>Was das bedeutet</h2><p>Dein Profil und deine Inhalte sind während der Sperre nicht öffentlich sichtbar. Du kannst aktuell keine Beiträge veröffentlichen, Nachrichten versenden oder anderen folgen.</p><p class="kn-ban-muted">Vorläufige Wiederherstellungsfrist: ${dateTimeFull(state.graceUntil)}. Diese Frist bedeutet keine automatische endgültige Löschung.</p></section>${appeal}<section class="kn-ban-section"><h2>Was du tun kannst</h2><p>Du kannst die Entscheidung anfechten und dich über weitere Beschwerdemöglichkeiten informieren.</p><div class="kn-ban-links"><a href="/legal/beschwerden">Beschwerdemöglichkeiten</a><a href="/legal/datenschutz">Datenschutz</a></div></section><button type="button" class="button outlined kn-ban-logout" data-logout>Abmelden</button></main></div>`;
 }catch(err){const el=$('.kn-ban-loading');if(el)el.textContent='Die Informationen konnten nicht geladen werden: '+err.message;}
}

function display(html){if(model.me&&['feed','explore'].includes(model.route)&&!html.includes('class="spinner"'))model.viewCache[model.route]=html;$('#content').innerHTML=html;}
function page(title,subtitle='',right=''){return `<div class="page-head"><div><h1>${esc(title)}</h1>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${right}</div>`;}
const empty=(emoji,title,description)=>`<div class="empty"><span class="emoji">${emoji}</span><h3>${esc(title)}</h3><p>${esc(description||'')}</p></div>`;
// Netlify Free: sichtbarkeitsabhängiges, begrenztes Polling statt WebSockets.
// Chat nur bei offenem Thread etwa alle 12s, ungelesene Mitteilungen alle 36s.
// Interaktionen aktualisieren das UI sofort und gleichen danach den Server ab.
async function refreshCurrentThread(){
 if(!model.me||model.route!=='messages'||!model.activeThread||document.hidden)return;
 const id=model.activeThread;
 const root=$('#messageScroll');
 if(!root||root.querySelector('.bubble.sending'))return;
 const result=await api('/social/dm/'+encodeURIComponent(id));
 if(model.activeThread!==id)return;
 const sig=result.messages.map(m=>m.id+':'+(m.reactions||[]).map(r=>r.userId+r.emoji).join('')).join('|');
 if(sig===model.threadSignature)return;
 model.threadSignature=sig;
 model.messageCache=new Map(result.messages.map(m=>[m.id,m]));
 const atEnd=root.scrollHeight-root.scrollTop-root.clientHeight<80;
 root.innerHTML=result.messages.map(bubbleHtml).join('');
 if(atEnd)root.scrollTop=root.scrollHeight;
}
function connectLive(){
 disconnectLive();
 model.pollTicks=0;model.pollBusy=false;
 model.poll=setInterval(async()=>{
   if(!model.me||document.hidden||model.pollBusy)return;
   model.pollBusy=true;
   try{
     model.pollTicks++;
     if(model.route==='messages'&&model.activeThread)await refreshCurrentThread();
     if(model.pollTicks%3===0){
       await updateBadge();
       await updateMessageBadge();
       if(model.route==='notifications')await renderNotifications();
     }
   }catch{}finally{model.pollBusy=false;}
 },12000);
}
function disconnectLive(){clearInterval(model.poll);model.poll=null;if(model.ws){model.ws.close();model.ws=null;}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&model.me){updateBadge();updateMessageBadge();if(model.route==='messages'&&model.activeThread)refreshCurrentThread().catch(()=>{});}});
function setMessageBadge(n){model.messageUnread=Math.max(0,Number(n)||0);const el=$('#mobileMessageUnread');if(el){el.hidden=model.messageUnread<1;el.textContent=model.messageUnread>99?'99+':String(model.messageUnread)}}
async function updateMessageBadge(){if(!model.me)return;try{const r=await api('/social/dm/unread');setMessageBadge(r.count||0)}catch{}}
function setBadgeNumber(n){model.unreadCount=Math.max(0,Number(n)||0);for(const id of ['navBadge','mobileBadge']){const el=$('#'+id);if(el){el.hidden=n<=0;el.textContent=n>99?'99+':String(n)}}}
async function updateBadge(){if(!model.me)return;try{const r=await api('/unread');setBadgeNumber(Number(r.count)||0)}catch{}}
async function navigate(route,options={}){if(model.me?.suspended){mountSuspended(model.me);return;}closeMenu();if(!options.pop){const paths={feed:'/home',explore:'/entdecken',messages:'/nachrichten',notifications:'/mitteilungen',profile:'/profil/'+(model.me?.id||''),saved:'/gespeichert',activity:'/aktivitaeten',settings:'/einstellungen',support:'/support',admin:'/team'};const next=paths[route];if(next&&location.pathname!==next)history.pushState({route},'',next);}if(route==='create'){showComposer();return;}model.route=route;document.body.dataset.view=route;model.navRequestId++;model.activeThread=null;shell();$('#rightRail').innerHTML=rightRail();display(model.viewCache[route]||'<div class="spinner"></div>');try{
  if(route==='feed')await renderFeed(false,!!options.following);
  else if(route==='explore')await renderExplore();
  
  
  else if(route==='saved')await renderSaved();
   else if(route==='activity')await renderActivity();
  
  else if(route==='messages')await renderMessages();
  else if(route==='notifications')await renderNotifications();
  else if(route==='profile')await renderProfile(model.me.id);
  else if(route==='settings')await renderSettings();
  else if(route==='admin')await renderAdmin();
  else if(route==='support')await renderSupport();
  else navigate('feed');
}catch(e){display(empty('⚠',tr('tryAgain'),e.message));}}
function rightRail(){const u=model.me;return `<section class="kn-rail-profile">${avatar(u)}<div><strong>${esc(u.name||u.username||'Mein Profil')}</strong><small>@${esc(u.username||'')}</small></div><button class="tiny-btn" data-go="profile">Profil</button></section><section class="kn-rail-discovery"><div class="kn-rail-title"><h3>Vorschläge für dich</h3><button class="tiny-btn" data-go="explore">Alle ansehen</button></div><div id="knSuggestedList" aria-live="polite"><span class="tiny">Leute entdecken …</span></div></section><div class="kn-rail-bottom"><p>Entdecke echte Menschen, teile Fotos und bleib im Gespräch.</p><a href="/legal/datenschutz">Datenschutz</a> · <a href="/legal/impressum">Impressum</a></div>`;}
async function loadSuggestions(){let data;try{if(model.suggestions&&Date.now()-model.suggestedAt<60000)data=model.suggestions;else{data=(await api('/social/suggestions')).people||[];model.suggestions=data;model.suggestedAt=Date.now();}}catch{return;}const html=data.map(u=>`<div class="kn-suggestion">${avatar(u,'small')}<button type="button" class="kn-suggestion-name" data-profile="${esc(u.id)}"><strong>${esc(u.name||u.username)} ${badge(u)}</strong><small>@${esc(u.username)}</small></button><button class="tiny-btn" data-suggestion-follow="${esc(u.id)}">Folgen</button></div>`).join('')||'<p class="tiny">Noch keine neuen Profile zum Entdecken.</p>';const rail=$('#knSuggestedList');if(rail&&model.route==='feed')rail.innerHTML=html;const mobile=$('#knMobileSuggestions');if(mobile&&['feed','explore'].includes(model.route))mobile.innerHTML=html;}

function postCard(p,priority=false){const name=p.name||p.username||'user',media=p.mediaId?(p.mediaMime?.startsWith('video/')?'':`<button class="post-image-open" data-full-image="${esc(p.mediaId)}" aria-label="Beitragsbild vollständig anzeigen"><img class="post-photo" loading="${priority?'eager':'lazy'}" fetchpriority="${priority?'high':'auto'}" decoding="async" alt="${esc(name)}" src="${socialImg(p.mediaId)}"></button>`):'';return `<article class="post" data-post="${esc(p.id)}"><div class="post-top">${avatar(p)}<div class="post-name"><button class="name-button" data-profile="${esc(p.userId||p.id)}">${esc(name)} ${badge(p)}</button><small>@${esc(p.username)} · ${dateTime(p.createdAt)}</small></div><button class="icon-button post-menu" title="${tr('report')}" data-report="post:${esc(p.id)}">${icon('more')}</button></div>${media}<div class="post-actions"><button class="icon-button ${p.liked?'active':''}" data-like="${esc(p.id)}" title="${tr('like')}">${icon('heart')}</button><button class="icon-button" data-comments="${esc(p.id)}" title="${tr('comments')}">${icon('comment')}</button><button class="icon-button save ${p.saved?'active':''}" data-save="${esc(p.id)}" title="${tr('save')}">${icon('bookmark')}</button></div><div class="post-meta"><span class="likes-count" data-count="${Number(p.likes)||0}">${formatCount(p.likes)}</span> ${tr('like').toLowerCase()}</div>${p.caption?`<div class="post-copy"><button class="name-button caption-author" data-profile="${esc(p.userId||p.id)}">${esc(p.username)}</button>${richMentions(p.caption)}</div>`:''}<button class="post-comment-link" data-count="${Number(p.comments)||0}" data-comments="${esc(p.id)}">${formatCount(p.comments)} ${tr('comments').toLowerCase()}</button>${p.userId===model.me?.id?`<button class="post-comment-link" data-delete-post="${esc(p.id)}">${tr('delete')}</button>`:''}</article>`;}
function richMentions(value){return String(value||'').split(/(@[a-z0-9._]{10,24})/gi).map(v=>/^@[a-z0-9._]{10,24}$/i.test(v)?`<button type="button" class="kn-mention" data-mention-user="${esc(v.slice(1))}">${esc(v)}</button>`:esc(v)).join('');}
function storyVisualStyle(raw){let v;try{v=typeof raw==='string'?JSON.parse(raw):raw||{};}catch{v={};}const num=(n,d,mi,ma)=>Math.min(ma,Math.max(mi,Number.isFinite(Number(n))?Number(n):d));const color=/^#[a-f0-9]{6}$/i.test(v.color||'')?v.color:'#ffffff';return `left:${num(v.x,50,12,88)}%;top:${num(v.y,50,12,88)}%;font-size:${num(v.size,28,18,42)}px;color:${color};text-align:${['left','center','right'].includes(v.align)?v.align:'center'}`;}
function storyImageZoom(raw){try{const v=typeof raw==='string'?JSON.parse(raw):raw||{};return Math.min(2,Math.max(1,Number(v.zoom||100)/100));}catch{return 1;}}
function storyButton(s){return `<button class="story-button" data-story="${esc(s.id)}"><span class="story-ring">${avatar(s)}</span><span>${esc(s.username||s.name)}</span></button>`;}
function exploreCard(p){const label=p.name||p.username||'Profil',photo=p.mediaId&&!p.mediaMime?.startsWith('video/');return `<button type="button" class="kn-discover-tile" data-open-post="${esc(p.id)}" aria-label="Beitrag von ${esc(label)} öffnen">${photo?`<img loading="lazy" decoding="async" src="${socialImg(p.mediaId)}" alt="">`:`<span>${esc((p.caption||'Beitrag').slice(0,120))}</span>`}<span class="kn-discover-caption">♡ ${formatCount(p.likes)}</span></button>`;}
