 const name=esc(p.name||p.username||'Profil');const poster=avatar(p,'small');
 const isPhoto=p.mediaId&&!p.mediaMime?.startsWith('video/');model.openCommentPost=id;model.openCommentCreator=p.userId||'';
 const media=isPhoto?`<img src="${socialImg(p.mediaId)}" alt="Foto von ${name}" loading="eager" decoding="async">`:`<div class="kn-post-text-tile">${esc(p.caption||'Beitrag')}</div>`;
