async function reactToMessage(id,emoji='❤️'){
 const thread=model.activeThread;if(!thread)return;
 if(!model.reactionPending)model.reactionPending=new Set();if(model.reactionPending.has(id))return;
 const message=model.messageCache?.get(id);if(!message)return refreshCurrentThread();
 model.reactionPending.add(id);
 const before=(message.reactions||[]).map(r=>({...r}));const others=before.filter(r=>r.userId!==model.me?.id);
 const mine=before.find(r=>r.userId===model.me?.id);
 message.reactions=mine?.emoji===emoji?others:[...others,{userId:model.me.id,emoji}];
 const paint=()=>{const bubble=document.querySelector(`[data-bubble="${CSS.escape(id)}"]`),row=bubble?.closest('.bubble-row');if(row)row.outerHTML=bubbleHtml(message);};paint();
 try{const result=await post('/social/dm/'+encodeURIComponent(thread)+'/messages/'+encodeURIComponent(id)+'/react',{emoji});message.reactions=result.emoji?[...others,{userId:model.me.id,emoji:result.emoji}]:others;paint();model.threadSignature=null;}
 catch(error){message.reactions=before;paint();toast(error.message||'Reaktion konnte nicht gespeichert werden.');}
 finally{model.reactionPending.delete(id);}
}
